 
/**
 * src/data/v2/index.js — Phase 4a
 * ─────────────────────────────────────────────────────────────────────
 * Single entry-point for the canonical v2 product datasets.
 *
 * These files are generated by scripts/migrate-all.mjs from the legacy
 * src/data/products.js and src/data/supplements.js sources.
 *
 * Re-run the migration script whenever legacy source data changes:
 *   node scripts/migrate-all.mjs
 *   # → updates dist/data/ and src/data/v2/
 *
 * Shape of each record: see src/schemas/productSchema.js
 */

export let products = [];
export let supplements = [];
export let catalog = [];

let _byName = new Map();
let _bySlug = new Map();
export let categories = [];

export function initializeData(data) {
  products = data.products || [];
  supplements = data.supplements || [];
  catalog = data.catalog || [];

  _byName = new Map(catalog.map((p) => [(p.name ?? '').toLowerCase().trim(), p]));
  _bySlug = new Map(catalog.map((p) => [p.slug ?? '', p]));
  categories = [...new Set(catalog.map((p) => p.category).filter(Boolean))].sort();
}

/** Find a v2 product by its canonical name (case-insensitive). */
export function findByName(name) {
  return _byName.get((name ?? '').toLowerCase().trim()) ?? null;
}

/** Find a v2 product by its slug. */
export function findBySlug(slug) {
  return _bySlug.get(slug ?? '') ?? null;
}
